CREATE PROCEDURE import_rows()
BEGIN
  DECLARE done INT DEFAULT 0; DECLARE v_sku VARCHAR(10); DECLARE v_qty INT;
  DECLARE c CURSOR FOR SELECT sku, qty FROM staging;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;
