DELIMITER //
CREATE PROCEDURE fill_seq(IN k INT)
BEGIN
  DECLARE i INT DEFAULT 0;
  lp: LOOP
    SET i = i + 1;
    IF i > k THEN LEAVE lp; END IF;       -- exit
    IF i = 2 THEN ITERATE lp; END IF;      -- skip 2
    INSERT INTO seq VALUES (i);
  END LOOP lp;
END //
DELIMITER ;
