CREATE PROCEDURE odd_sum(OUT s INT)
BEGIN
  DECLARE i INT DEFAULT 0;
  SET s = 0;
  lp: LOOP
    SET i = i + 1;
    IF i > 10 THEN LEAVE lp; END IF;
    IF i MOD 2 = 0 THEN ITERATE lp; END IF;
    SET s = s + i;
  END LOOP;
END //
DELIMITER ;
CALL odd_sum(@s); SELECT @s;

-- OUTPUT:
-- @s
-- 25

