CREATE PROCEDURE sum_odd(IN p_n INT, OUT p_sum INT)
BEGIN
  DECLARE i INT DEFAULT 0;
  SET p_sum = 0;
  lp: LOOP
    SET i = i + 1;
    IF i > p_n THEN LEAVE lp; END IF;
    IF i MOD 2 = 0 THEN ITERATE lp; END IF;
    SET p_sum = p_sum + i;
  END LOOP;
END //
DELIMITER ;
