-- Session A starts a snapshot, session B changes the row, A still sees the old value
CREATE TABLE acct (id INT PRIMARY KEY, bal INT);
INSERT INTO acct VALUES (1, 100);

-- Session A:
START TRANSACTION;
SELECT bal FROM acct WHERE id = 1;          -- snapshot taken at this first read

-- Session B (autocommit):
UPDATE acct SET bal = 150 WHERE id = 1;

-- Session A again:
SELECT bal FROM acct WHERE id = 1;

-- OUTPUT:
-- A first read : 100
-- A second read: 100     <- still the snapshot, B's change is invisible to A

-- READ COMMITTED creates a fresh read view for EVERY statement
SET SESSION TRANSACTION ISOLATION LEVEL READ COMMITTED;
START TRANSACTION;
SELECT bal FROM acct WHERE id = 1;           -- 100
-- other session commits: UPDATE acct SET bal = 150 WHERE id = 1;
SELECT bal FROM acct WHERE id = 1;           -- new statement, new read view
COMMIT;

-- OUTPUT:
-- first : 100
-- second: 150      <- non-repeatable read is allowed at READ COMMITTED

SET SESSION TRANSACTION ISOLATION LEVEL READ COMMITTED;
START TRANSACTION;
SELECT COUNT(*) FROM orders;      -- 1000
-- another session commits 5 rows
SELECT COUNT(*) FROM orders;      -- 1005
COMMIT;

-- OUTPUT:
-- 1000
-- 1005

START TRANSACTION WITH CONSISTENT SNAPSHOT;
SELECT COUNT(*) FROM orders;
-- other sessions insert more rows and commit
SELECT COUNT(*) FROM orders;
COMMIT;

-- OUTPUT:
-- COUNT(*)
-- 1000
-- COUNT(*)
-- 1000       (same count: the read view hides the later commits)

SET SESSION TRANSACTION ISOLATION LEVEL READ COMMITTED;
START TRANSACTION;
SELECT COUNT(*) FROM orders;        -- 1000
-- another session commits 5 rows
SELECT COUNT(*) FROM orders;        -- 1005 (new read view for this statement)
COMMIT;
mysqldump --single-transaction shop > shop.sql      -- consistent dump without blocking writers

-- OUTPUT:
-- 1000
-- 1005

